// Format filters and showtimes for the static pages generated by
// scripts/build-site.mjs: a movie's page (theatres showing it) and the movies/
// index. Without this script both list everything. With it, picking formats
// narrows the list to entries in any of them, and carries the selection into
// the URL and into each link (movie and theatre pages read the same "formats"
// param).
//
// A movie's page also lists dates only, to stay small and crawlable. Here the
// movies/<slug>/showtimes.json beside it is fetched and the times go under
// each theatre, grouped by day and format, as ticket links, with a strip of
// days to look at just one. Until that file loads (or if it can't), the
// page's own dates stay as they are.
//
// Hovering a time (or tapping it, on a touch screen) previews its seat map
// (see seatmap.js, which movie pages load first). The seats aren't in
// showtimes.json, which would make every page several times bigger for the
// few visitors who look: they're read from the theatre's own data file the
// first time one of its times is asked for.
const filterEl = document.getElementById("movie-filter");
const countEl = document.getElementById("movie-count");

// The province a visitor last opened on a movie page, reopened on the next
// one. A per-browser convenience, so storage failures are ignored.
const PROVINCE_KEY = "cinescan:province";

// Days listed under each theatre until its "more days" button is used. A
// release that plays every day would otherwise be a wall of times, while a
// rare format (Stars & Strollers, say) rarely has more than this.
const DAYS_SHOWN = 3;

// Few enough theatres left after filtering that every province opens at once,
// saving a click each. (build-site.mjs opens a whole small release likewise.)
const OPEN_ALL_MAX_THEATRES = 12;

function readStoredProvince() {
  try {
    return localStorage.getItem(PROVINCE_KEY);
  } catch {
    return null;
  }
}

function storeProvince(province) {
  try {
    if (province) localStorage.setItem(PROVINCE_KEY, province);
    else localStorage.removeItem(PROVINCE_KEY);
  } catch {
    // Private mode or blocked storage: the page still works, just forgets.
  }
}

// Sets the "formats" param on a URL, or removes it for an empty selection.
function withFormats(href, selected) {
  const url = new URL(href, document.baseURI);
  if (selected.size) url.searchParams.set("formats", [...selected].join(","));
  else url.searchParams.delete("formats");
  return url;
}

// What the collapsed filter's toggle says is selected: "All formats", or
// the first couple of tags, e.g. "IMAX, 4DX +1".
function selectionSummary(selected) {
  if (selected.size === 0) return "All formats";
  const tags = [...selected];
  return tags.length > 2 ? `${tags.slice(0, 2).join(", ")} +${tags.length - 2}` : tags.join(", ");
}

// Wires up the chips and calls onChange(selected) with the selected tags
// (empty means everything) on load and after every change.
function setupFormatFilter(onChange) {
  const chips = [...filterEl.querySelectorAll(".format-chip")];
  const allBtn = filterEl.querySelector(".format-clear-btn");
  const knownTags = new Set(chips.map((chip) => chip.dataset.tag));
  const urlFormats = new URLSearchParams(location.search).get("formats");
  let selected = new Set((urlFormats || "").split(",").filter((tag) => knownTags.has(tag)));

  // Only a long filter has a toggle (see COLLAPSE_FILTER_MIN_FORMATS in
  // build-site.mjs); on phones it hides the chips until opened.
  const toggle = document.getElementById("movie-filter-toggle");
  const stateEl = toggle?.querySelector(".filter-toggle-state");

  function apply() {
    for (const chip of chips) {
      const on = selected.has(chip.dataset.tag);
      chip.classList.toggle("active", on);
      chip.setAttribute("aria-pressed", String(on));
    }
    allBtn.classList.toggle("active", selected.size === 0);
    allBtn.setAttribute("aria-pressed", String(selected.size === 0));
    if (stateEl) stateEl.textContent = selectionSummary(selected);
    history.replaceState(history.state, "", withFormats(location.href, selected));
    onChange(selected);
  }

  for (const chip of chips) {
    chip.addEventListener("click", () => {
      const tag = chip.dataset.tag;
      if (selected.has(tag)) selected.delete(tag);
      else selected.add(tag);
      apply();
    });
  }
  allBtn.addEventListener("click", () => {
    selected = new Set();
    apply();
  });

  if (toggle) {
    const wrap = filterEl.closest(".movie-filter-wrap");
    toggle.hidden = false;
    toggle.addEventListener("click", () => {
      toggle.setAttribute("aria-expanded", String(wrap.classList.toggle("open")));
    });
  }

  filterEl.hidden = false;
  apply();
}

function plural(n, word) {
  return `${n} ${word}${n === 1 ? "" : "s"}`;
}

// Lower-case and accent-free, so "montreal" finds "Montréal". Same as
// normalize in app.js, which does this for its own theatre search.
function normalizeText(str) {
  return str
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .trim();
}

// "2:10 PM", for a "14:10" showtime. Same as formatTimeLabel in app.js.
function formatTimeLabel(timeStr) {
  const [h, m] = timeStr.split(":").map(Number);
  return `${h % 12 || 12}:${String(m).padStart(2, "0")} ${h < 12 ? "AM" : "PM"}`;
}

// "Thu, Nov 5", for a "YYYY-MM-DD" date. Same wording as the dates build-site.mjs
// writes into the page.
function formatDayLabel(dateStr) {
  return new Date(`${dateStr}T00:00:00Z`).toLocaleDateString("en-CA", {
    timeZone: "UTC",
    weekday: "short",
    month: "short",
    day: "numeric",
  });
}

const clockFormats = new Map();

// The date ("YYYY-MM-DD") and time ("HH:MM", 24-hour) at the moment in a time
// zone, which decides which of a theatre's sessions are over: that depends on
// where the theatre is, not where the visitor is.
function clockAt(timeZone, now = new Date()) {
  let format = clockFormats.get(timeZone);
  if (!format) {
    format = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23",
    });
    clockFormats.set(timeZone, format);
  }
  const parts = Object.fromEntries(format.formatToParts(now).map((part) => [part.type, part.value]));
  return { date: `${parts.year}-${parts.month}-${parts.day}`, time: `${parts.hour}:${parts.minute}` };
}

// One theatre's showtimes as a list of days, from the theatre's entry in
// showtimes.json (see movieShowtimes in build-site.mjs). Days before today at
// the theatre are dropped, since the page can be hours older than the visitor,
// and so are sessions outside the chosen formats (none chosen means all).
// Each day's rows are one format combination each, earliest first:
//
//   [{ date, today, rows: [{ formats, sessions: [{ time, url, seats, past }] }] }]
//
// `seats` marks sessions that have a seat map, and `past` those that have
// already started today.
function theatreDays(entry, combos, formats, now) {
  const days = [];
  for (const [date, sessions] of Object.entries(entry.days).sort(([a], [b]) => (a < b ? -1 : 1))) {
    if (date < now.date) continue;
    const rows = new Map();
    for (const [time, combo, url, seats] of sessions) {
      const tags = combos[combo];
      if (formats.size > 0 && !tags.some((tag) => formats.has(tag))) continue;
      if (!rows.has(combo)) rows.set(combo, { formats: tags, sessions: [] });
      rows.get(combo).sessions.push({ time, url, seats: seats === 1, past: date === now.date && time < now.time });
    }
    if (rows.size === 0) continue;
    days.push({
      date,
      today: date === now.date,
      rows: [...rows.values()].sort((a, b) => a.sessions[0].time.localeCompare(b.sessions[0].time)),
    });
  }
  return days;
}

// "Nov 4, 2026, 5:03 PM EST", for when a theatre's data was last scraped. Same
// as the "Last updated" time in app.js.
function updatedLabel(updatedAt) {
  return new Date(updatedAt).toLocaleString("en-US", {
    timeZone: "America/Toronto",
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    timeZoneName: "short",
  });
}

// A theatre's data file, read for its seat maps: which show a session's seats
// by its ticket link. (A link rather than the session's id since D-BOX seats
// are sold as a separate area of the same showing, as a second session with
// the same seats but its own link.) Sessions without a seat map are left out.
//
//   { asOf, bySession: Map(ticketUrl -> { layout, seats, runtimeMinutes }) }
function indexSeatFile(data) {
  const bySession = new Map();
  for (const day of data.days || []) {
    for (const movie of day.movies || []) {
      for (const session of movie.sessions || []) {
        const layout = data.auditoriums?.[session.layoutKey];
        if (session.ticketUrl && session.seats && layout) {
          bySession.set(session.ticketUrl, { layout, seats: session.seats, runtimeMinutes: movie.runtimeMinutes });
        }
      }
    }
  }
  return { asOf: data.updatedAt ? updatedLabel(data.updatedAt) : "", bySession };
}

const seatFiles = new Map(); // theatre slug -> promise of its indexSeatFile()

function loadSeatFile(slug) {
  let file = seatFiles.get(slug);
  if (!file) {
    // The same file (and path) the theatre's page loads. Revalidated each time
    // since seats sell out between scrapes, though it's cheap when unchanged.
    file = fetch(new URL(`data/${slug}.json`, document.baseURI), { cache: "no-cache" })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(indexSeatFile);
    seatFiles.set(slug, file);
    // Asked for again after a failure, it tries again.
    file.catch(() => seatFiles.delete(slug));
  }
  return file;
}

// The seat map for one of a theatre's showtimes (see seatmap.js), or null if
// its data file has none for it.
function seatMapFor(slug, session) {
  return loadSeatFile(slug).then((file) => {
    const found = file.bySession.get(session.url);
    return found && { ...found, time: session.time, asOf: file.asOf };
  });
}

function setupMoviePage() {
  const mainEl = document.querySelector(".movie-page");
  const barEl = document.getElementById("movie-day-bar");
  const searchEl = document.getElementById("movie-search"); // only on pages for many theatres
  const movieSlug = mainEl.dataset.movie;
  const theatreEls = [...document.querySelectorAll(".movie-theatre")];
  const provinceEls = [...document.querySelectorAll(".movie-province")];

  const stored = readStoredProvince();
  const storedEl = provinceEls.find((el) => el.dataset.province === stored);
  if (storedEl) storedEl.open = true;
  // Only a visitor's own clicks (keyboard activation fires "click" too) are
  // remembered, not "toggle": that also fires for sections opened here or
  // by the build, which would overwrite the visitor's choice.
  for (const provinceEl of provinceEls) {
    provinceEl.querySelector("summary").addEventListener("click", () => {
      const opening = !provinceEl.open; // the click's default action toggles it afterwards
      if (opening) storeProvince(provinceEl.dataset.province);
      else if (readStoredProvince() === provinceEl.dataset.province) storeProvince(null);
    });
  }

  // The page's own rows carry each format combination's badges (and their
  // colours), so the times reuse those instead of rebuilding them here.
  const badgesByCombo = new Map();
  for (const row of document.querySelectorAll(".movie-combos li[data-formats]")) {
    if (!badgesByCombo.has(row.dataset.formats)) {
      badgesByCombo.set(row.dataset.formats, row.querySelector(".format-badges"));
    }
  }

  // Shown when no theatre is left: nothing matches the search, or the page has
  // outlived its movie's run so that every showtime is in the past.
  const emptyEl = document.createElement("p");
  emptyEl.className = "movie-empty";
  emptyEl.hidden = true;
  const emptyText = document.createElement("span");
  const nowPlayingLink = document.createElement("a");
  nowPlayingLink.href = "movies/";
  nowPlayingLink.textContent = "See what's playing";
  emptyEl.append(emptyText, " ", nowPlayingLink);
  mainEl.appendChild(emptyEl);

  let formats = new Set(); // chosen formats; empty means all
  let query = ""; // what's typed in the search box, normalized; empty means every theatre
  let date = new URLSearchParams(location.search).get("date"); // chosen day; null means all
  let showtimes = null; // showtimes.json, once it has loaded
  const expanded = new Set(); // theatres whose "more days" were opened
  const visitorToday = new Date().toLocaleDateString("en-CA");

  function setDate(value) {
    date = value;
    const url = new URL(location.href);
    if (date) url.searchParams.set("date", date);
    else url.searchParams.delete("date");
    history.replaceState(history.state, "", url);
    update();
  }

  // One chip per day, plus "All days" first. A chip's data-date is its day, or
  // "" for "All days".
  function buildDayTrack(dates) {
    const track = document.createElement("div");
    track.className = "date-bar-track";
    const chip = (value, className, ...content) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = `date-chip ${className}`.trim();
      btn.dataset.date = value;
      btn.append(...content);
      btn.addEventListener("click", () => setDate(value || null));
      track.appendChild(btn);
      return btn;
    };
    const part = (className, text) => {
      const span = document.createElement("span");
      span.className = className;
      span.textContent = text;
      return span;
    };

    chip("", "date-chip-all", "All days");
    let month = "";
    for (const value of dates) {
      const day = new Date(`${value}T00:00:00Z`);
      if (value.slice(0, 7) !== month) {
        month = value.slice(0, 7);
        track.appendChild(
          part("date-bar-month", day.toLocaleDateString("en-CA", { timeZone: "UTC", month: "short" }))
        );
      }
      const isToday = value === visitorToday;
      const btn = chip(
        value,
        isToday ? "is-today" : "",
        part("date-chip-weekday", isToday ? "Today" : day.toLocaleDateString("en-CA", { timeZone: "UTC", weekday: "short" })),
        part("date-chip-day", String(day.getUTCDate()))
      );
      btn.setAttribute("aria-label", formatDayLabel(value) + (isToday ? ", today" : ""));
    }
    return track;
  }

  let barDates = null; // the days the strip was last built for

  // A strip of the days that have showtimes under the chosen formats, like
  // the theatre page's. It's a filter, not a jump: picking a day lists just
  // that day's showtimes at every theatre, and "All days" lists them all.
  // It's only rebuilt when those days change, not for each pick, so a chip
  // keeps keyboard focus and the strip its sideways scroll.
  function renderDayBar(dates) {
    const show = dates.length >= 2; // one day leaves nothing to choose
    barEl.hidden = !show;
    document.documentElement.classList.toggle("has-date-bar", show);
    if (!show) {
      barEl.replaceChildren();
      barDates = null;
      return;
    }

    if (dates.join(",") !== barDates) {
      barDates = dates.join(",");
      const scrolled = barEl.firstElementChild?.scrollLeft ?? 0;
      barEl.replaceChildren(buildDayTrack(dates));
      barEl.firstElementChild.scrollLeft = scrolled;
    }

    const track = barEl.firstElementChild;
    for (const btn of track.querySelectorAll(".date-chip")) {
      const on = btn.dataset.date === (date ?? "");
      btn.classList.toggle("active", on);
      btn.setAttribute("aria-pressed", String(on));
    }
    // A day carried in from a link or a format change can be off to the side.
    const active = track.querySelector(".date-chip.active");
    if (date && active) {
      const t = track.getBoundingClientRect();
      const c = active.getBoundingClientRect();
      if (c.left < t.left || c.right > t.right) track.scrollLeft += c.left - t.left - (t.width - c.width) / 2;
    }
  }

  // Replaces a theatre's dates with its showtimes for the given days.
  function renderSchedule(theatreEl, days) {
    let box = theatreEl.querySelector(".movie-schedule");
    if (!box) {
      box = document.createElement("div");
      box.className = "movie-schedule";
      theatreEl.appendChild(box);
    }

    const slug = theatreEl.dataset.theatre;
    // A chosen day is shown whole; "All days" stops at a few until asked.
    const limit = date ? days.length : DAYS_SHOWN;
    const open = expanded.has(slug);
    const listed = open ? days : days.slice(0, limit);

    const list = document.createElement("dl");
    for (const day of listed) {
      const row = document.createElement("div");
      row.className = "movie-day";

      const label = document.createElement("dt");
      label.append(formatDayLabel(day.date));
      if (day.today) {
        const today = document.createElement("span");
        today.className = "movie-day-today";
        today.textContent = "Today";
        label.appendChild(today);
      }

      const times = document.createElement("dd");
      for (const { formats: tags, sessions } of day.rows) {
        const combo = document.createElement("div");
        combo.className = "movie-combo";
        const badges = badgesByCombo.get(tags.join("|"));
        if (badges) combo.appendChild(badges.cloneNode(true));
        const timesEl = document.createElement("span");
        timesEl.className = "movie-times";
        for (const session of sessions) {
          const el = document.createElement(session.url ? "a" : "span");
          el.className = session.past ? "session is-past" : "session";
          el.textContent = formatTimeLabel(session.time);
          if (session.url) {
            el.href = session.url;
            el.target = "_blank";
            el.rel = "noopener";
          }
          // Not for a session that has started, which isn't worth a look at the
          // seats. A page cached from before seatmap.js existed goes without.
          if (session.seats && !session.past && typeof SeatMap !== "undefined") {
            SeatMap.attach(el, () => seatMapFor(slug, session));
          }
          timesEl.appendChild(el);
        }
        combo.appendChild(timesEl);
        times.appendChild(combo);
      }
      row.append(label, times);
      list.appendChild(row);
    }

    const children = [list];
    if (days.length > limit) {
      const more = document.createElement("button");
      more.type = "button";
      more.className = "movie-more-days";
      more.setAttribute("aria-expanded", String(open));
      const rest = days.length - limit;
      more.textContent = open ? "Show fewer days" : `Show ${plural(rest, "more day")}`;
      more.addEventListener("click", () => {
        if (open) expanded.delete(slug);
        else expanded.add(slug);
        renderSchedule(theatreEl, days);
        // The button was just replaced; keep focus on it without moving the page.
        box.querySelector(".movie-more-days").focus({ preventScroll: true });
      });
      children.push(more);
    }
    box.replaceChildren(...children);
  }

  function update() {
    // What each theatre has under the chosen formats, once showtimes.json has
    // loaded; until then (or for a theatre missing from it) the page's own
    // dates are filtered by format instead.
    const daysByTheatre = new Map();
    if (showtimes) {
      const dates = new Set();
      for (const theatreEl of theatreEls) {
        const entry = showtimes.theatres[theatreEl.dataset.theatre];
        if (!entry) continue;
        const days = theatreDays(entry, showtimes.combos, formats, clockAt(entry.tz));
        daysByTheatre.set(theatreEl, days);
        for (const day of days) dates.add(day.date);
      }
      if (date && !dates.has(date)) {
        // A day that these formats don't play on, e.g. from an old link.
        date = null;
        const url = new URL(location.href);
        url.searchParams.delete("date");
        history.replaceState(history.state, "", url);
      }
      renderDayBar([...dates].sort());
    }
    // A day from the URL means nothing until the days are known.
    const chosen = showtimes ? date : null;

    let shown = 0;
    for (const theatreEl of theatreEls) {
      const days = daysByTheatre.get(theatreEl);
      // Matched on the name as shown: the theatre's own, then its city.
      const named =
        query === "" ||
        normalizeText(theatreEl.querySelector(".movie-theatre-name").textContent).includes(query);
      let visible;
      if (days) {
        const listed = chosen ? days.filter((day) => day.date === chosen) : days;
        visible = named && listed.length > 0;
        theatreEl.querySelector(".movie-combos").hidden = true;
        if (visible) renderSchedule(theatreEl, listed);
      } else {
        let anyCombo = false;
        for (const comboEl of theatreEl.querySelectorAll("[data-formats]")) {
          const comboVisible =
            formats.size === 0 || comboEl.dataset.formats.split("|").some((t) => formats.has(t));
          comboEl.hidden = !comboVisible;
          anyCombo ||= comboVisible;
        }
        visible = named && anyCombo;
      }
      theatreEl.hidden = !visible;
      if (visible) shown++;

      // The theatre's page opens on this movie, so its showtimes aren't left
      // to be found among the other movies there.
      const link = theatreEl.querySelector("[data-theatre-link]");
      const url = withFormats(link.getAttribute("href"), formats);
      url.searchParams.set("movie", movieSlug);
      link.href = url;
    }

    const narrowed = formats.size > 0 || chosen !== null || query !== "";
    const visibleProvinces = [];
    for (const provinceEl of provinceEls) {
      const all = provinceEl.querySelectorAll(".movie-theatre").length;
      const visible = provinceEl.querySelectorAll(".movie-theatre:not([hidden])").length;
      provinceEl.hidden = visible === 0;
      provinceEl.querySelector(".movie-province-count").textContent = narrowed
        ? `${visible} of ${plural(all, "theatre")}`
        : plural(all, "theatre");
      if (visible) visibleProvinces.push(provinceEl);
    }
    // Nothing much left to choose between, so save the extra clicks. Someone
    // searching has asked for those theatres, so they're never left folded.
    if (visibleProvinces.length === 1 || query !== "" || (narrowed && shown <= OPEN_ALL_MAX_THEATRES)) {
      for (const provinceEl of visibleProvinces) provinceEl.open = true;
    }

    emptyEl.hidden = shown > 0;
    if (shown === 0) {
      emptyText.textContent =
        query !== ""
          ? "No theatres match that search."
          : "No upcoming showtimes right now; this movie may have finished its run.";
      nowPlayingLink.hidden = query !== "";
    }
    countEl.textContent =
      shown === 0
        ? "" // the message above says why
        : narrowed
        ? `Showing ${shown} of ${plural(theatreEls.length, "theatre")}${chosen ? ` on ${formatDayLabel(chosen)}` : ""}`
        : plural(theatreEls.length, "theatre");
  }

  if (searchEl) {
    searchEl.hidden = false;
    searchEl.addEventListener("input", () => {
      query = normalizeText(searchEl.value);
      update();
    });
  }

  setupFormatFilter((selected) => {
    formats = selected;
    update();
  });

  fetch(mainEl.dataset.showtimes, { cache: "no-cache" })
    .then((res) => {
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    })
    .then((data) => {
      showtimes = data;
      update();
    })
    .catch((err) => console.warn("Couldn't load showtimes; listing dates only:", err));
}

function setupMovieIndex() {
  const cardEls = [...document.querySelectorAll(".movie-grid > li")];
  const sectionEls = [...document.querySelectorAll(".movie-index-section")];

  setupFormatFilter((selected) => {
    let shown = 0;
    for (const cardEl of cardEls) {
      const counts = JSON.parse(cardEl.dataset.counts);
      const matching = [...selected].filter((tag) => counts[tag]);
      const visible = selected.size === 0 || matching.length > 0;
      cardEl.hidden = !visible;
      if (visible) shown++;

      const link = cardEl.querySelector(".movie-card");
      link.href = withFormats(link.getAttribute("href"), selected);
      for (const badge of cardEl.querySelectorAll(".format-badge[data-extra]")) {
        badge.hidden = !selected.has(badge.dataset.tag);
      }

      // e.g. "12 theatres in IMAX · 3 in 4DX" instead of the overall count.
      const metaEl = cardEl.querySelector(".movie-card-meta");
      metaEl.dataset.all ??= metaEl.textContent;
      const byFormat = matching.map(
        (tag, i) => `${i === 0 ? plural(counts[tag], "theatre") : counts[tag]} in ${tag}`
      );
      metaEl.textContent = selected.size
        ? [cardEl.dataset.opens, ...byFormat].filter(Boolean).join(" · ")
        : metaEl.dataset.all;
    }
    for (const sectionEl of sectionEls) {
      sectionEl.hidden = !sectionEl.querySelector(".movie-grid > li:not([hidden])");
    }
    countEl.textContent = selected.size
      ? `Showing ${shown} of ${plural(cardEls.length, "movie")}`
      : plural(cardEls.length, "movie");
  });
}

